export default function MenuCard({
  item,
  quantity = 0,
  addToCart,
  removeFromCart
}) {
  const outOfStock = item.stock <= 0;

  return (
    <div className={`menu-card ${outOfStock ? "out" : ""}`}>
      
      {/* ✅ BADGES */}
      <div className="menu-badges">
        {item.is_top_rated && (
          <span className="menu-badge top-rated">⭐ Top Rated</span>
        )}
        {item.is_popular && (
          <span className="menu-badge popular">🔥 Popular</span>
        )}
      </div>

      <h3>{item.name}</h3>
      <p className="price">₹{item.price}</p>

      <div className="rating">
        ⭐ {item.avg_rating || 0} | Sold: {item.total_sold || 0}
      </div>

      <div className={`stock ${outOfStock ? "out" : ""}`}>
        Stock: {item.stock}
      </div>

      {/* CONTROLS */}
      {outOfStock ? (
        <button className="btn-disabled" disabled>
          Unavailable
        </button>
      ) : quantity === 0 ? (
        <button className="btn-add" onClick={() => addToCart(item)}>
          ADD
        </button>
      ) : (
        <div className="qty-box">
          <button
            onClick={() => removeFromCart(item.id)}
            disabled={quantity <= 0}
          >
            −
          </button>

          <span>{quantity}</span>

          <button onClick={() => addToCart(item)}>+</button>
        </div>
      )}
    </div>
  );
}
